fast_pseudocode:
# Autotune decorator AND grid lambda updated together
@triton.autotune(
    configs=[
        Config({'XBLOCK': 128}, num_warps=4),
        Config({'XBLOCK': 256}, num_warps=4),
        Config({'XBLOCK': 512}, num_warps=8),
        Config({'XBLOCK': 1024}, num_warps=8),
    ],
    key=['xnumel'],
)
@triton.jit
def kernel(..., XBLOCK: tl.constexpr):
    ...

# Grid MUST use meta to reflect autotuned tile sizes
grid = lambda meta: (cdiv(xnumel, meta['XBLOCK']), cdiv(ynumel, meta['YBLOCK']))
